// Bundles public/ into worker/static.generated.js so the Cloudflare Worker can
// serve the app's files itself. Removing Wrangler's separate asset upload
// avoids an upload path that some network proxies break. Run after any change
// under public/ (npm run cloud:deploy does this). `--check` fails if stale.
import { createHash } from 'node:crypto';
import { readFileSync, readdirSync, statSync, writeFileSync, existsSync } from 'node:fs';
import { dirname, extname, join, relative } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const pub = join(root, 'public');
const out = join(root, 'worker', 'static.generated.js');
const TYPES = {
  '.html': 'text/html; charset=utf-8', '.js': 'text/javascript; charset=utf-8', '.css': 'text/css; charset=utf-8',
  '.svg': 'image/svg+xml', '.png': 'image/png', '.ico': 'image/x-icon', '.json': 'application/json; charset=utf-8',
  '.webmanifest': 'application/manifest+json; charset=utf-8',
};

const walk = (dir) => readdirSync(dir).flatMap((name) => {
  const path = join(dir, name);
  return statSync(path).isDirectory() ? walk(path) : [path];
});

const files = walk(pub)
  .map((file) => '/' + relative(pub, file).split('\\').join('/'))
  .filter((url) => !url.split('/').some((part) => part.startsWith('_') || part.startsWith('.')))
  .sort();

const entries = files.map((url) => {
  const body = readFileSync(join(pub, url.slice(1))).toString('base64');
  const type = TYPES[extname(url)] ?? 'application/octet-stream';
  return `  ${JSON.stringify(url)}: { type: ${JSON.stringify(type)}, base64: ${JSON.stringify(body)} },`;
});

const source = `// GENERATED by scripts/bundle-static.js from public/. Do not edit by hand.\n` +
  `export const STATIC_FILES = {\n${entries.join('\n')}\n};\n`;

const hash = createHash('sha256').update(source).digest('hex').slice(0, 16);
if (process.argv.includes('--check')) {
  if (!existsSync(out) || readFileSync(out, 'utf8') !== source) {
    console.error('worker/static.generated.js is out of date. Run: node scripts/bundle-static.js');
    process.exit(1);
  }
} else {
  writeFileSync(out, source);
  console.log(`Bundled ${files.length} files into worker/static.generated.js (${hash})`);
}
